  docker stop -t 120 zocalo
  code="$(docker inspect -f '{{.State.ExitCode}}' zocalo)"
  [ "$code" = "137" ] && echo "WARNING: zocalo was SIGKILLed; Postgres did not stop cleanly" >&2
  docker rm zocalo
fi

docker run -d --name zocalo \
  --stop-timeout 120 \
  -p 80:80 -p 443:443 \
  -v zocalo-pgdata:/usr/local/pgsql/data \
  -v zocalo-certs:/etc/letsencrypt \
  -v zocalo-caddy:/root/.local/share/caddy \
